309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Override
311	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
312	        Owner owner = this.clinicService.findOwnerById(ownerId);
313	        if (owner != null) {
314	            Pet pet = owner.getPet(petId);
315	            if (pet != null) {
316	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
317	            }
318	        }
319	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	    }
321	
322	    /**
323	     * Emits an immutable structured {@code OWNER_CREATED} event to the {@code AUDIT} logger, alongside the
324	     * human-readable audit line. The event is a JSON object
325	     * {@code {seq, ownerId, memberId, membershipLevel, event}} where {@code seq} is a process-wide,
326	     * monotonically increasing sequence number across all creates.
327	     *
328	     * <p>The {@code memberId} field carries the owner's <em>current primary identifier</em> — see
329	     * {@link #primaryIdentifier(Owner)} — which is now the unified member id.
330	     *
331	     * @param owner    the freshly persisted owner
332	     * @param ownerDto its DTO projection, used for the derived membership level
333	     */
334	    private void emitOwnerCreatedEvent(Owner owner, OwnerDto ownerDto) {
335	        Map<String, Object> event = new LinkedHashMap<>();
336	        event.put("seq", OWNER_CREATED_SEQUENCE.incrementAndGet());
