406	    /**
407	     * Inclusive 4-digit postcode ranges permitted per city region, keyed by the region derived from the
408	     * city via {@link OwnerLocality}: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A region absent from
409	     * this table (i.e. {@code "UNKNOWN"}) imposes no range constraint, so any 4-digit postcode is accepted.
410	     */
411	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
412	        "NSW", new int[] {2000, 2099},
413	        "VIC", new int[] {3000, 3099},
414	        "QLD", new int[] {4000, 4099});
