416	    /**
417	     * Validates an owner's {@code postcode} when present. Postcode is optional: a {@code null} value is
418	     * accepted and left absent, keeping the create contract backward-compatible. When supplied it must be
419	     * a 4-digit value, and it must fall within the inclusive range for the city's region (NSW 2000-2099,
420	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
421	     *
422	     * @param postcode the submitted postcode, or {@code null} when omitted
423	     * @param city the owner's city, used to derive the region whose range constrains the postcode
424	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for the
425	     *                                  city's region
426	     */
427	    private void validatePostcode(String postcode, String city) {
428	        if (postcode == null) {
429	            return;
430	        }
431	        if (!postcode.matches("[0-9]{4}")) {
432	            throw new InvalidPostcodeException(postcode);
433	        }
434	        int[] range = REGION_POSTCODE_RANGE.get(OwnerLocality.of(city));
435	        if (range == null) {
436	            return;
437	        }
438	        int value = Integer.parseInt(postcode);
439	        if (value < range[0] || value > range[1]) {
440	            throw new InvalidPostcodeException(postcode);
441	        }
442	    }
