444	    /**
445	     * Normalizes a submitted telephone number into E.164 form, which becomes the stored and returned
446	     * value. Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are
447	     * kept as supplied; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
448	     * is dropped from the national digits. The result must be a {@code '+'} followed by 8 to 15 digits.
449	     * <p>
450	     * Where a per-country rule is defined the national-number length is validated against the country
451	     * code: {@code '+61'} (Australia) requires exactly 9 national digits and {@code '+1'} (NANP)
452	     * requires exactly 10.
453	     *
454	     * @param telephone the raw telephone value from the request
455	     * @return the E.164 telephone (a {@code '+'} followed by 8 to 15 digits)
456	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
457	     */
458	    private String normalizeTelephone(String telephone) {
459	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()\\-]", "");
460	        String digits;
461	        if (cleaned.startsWith("+")) {
462	            digits = cleaned.substring(1);
463	        } else {
464	            // No country code supplied: assume Australia (+61) and drop a single leading '0'.
465	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
466	            digits = "61" + national;
467	        }
468	        if (!digits.matches("[0-9]{8,15}")) {
469	            throw new InvalidTelephoneException(cleaned);
470	        }
471	        // Validate the national-number length against the country code where a rule is defined.
472	        if (digits.startsWith("61") && digits.length() - 2 != 9) {
473	            throw new InvalidTelephoneException(cleaned);
474	        }
475	        if (digits.startsWith("1") && digits.length() - 1 != 10) {
476	            throw new InvalidTelephoneException(cleaned);
477	        }
478	        return "+" + digits;
479	    }
