486	     * @param email the raw email value from the request, or {@code null} if omitted
487	     * @return the lower-cased email, or {@code null} if none was supplied
488	     * @throws InvalidEmailException if a non-null email is not a syntactically valid address
489	     */
490	    private String normalizeEmail(String email) {
491	        if (email == null) {
492	            return null;
493	        }
494	        String trimmed = email.strip();
495	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
496	            throw new InvalidEmailException(email);
497	        }
498	        String normalized = trimmed.toLowerCase(Locale.ROOT);
499	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
500	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
501	            throw new DisposableEmailDomainException(domain);
