506	    /**
507	     * Applies the owner's address in whichever form the request supplied, preferring the structured
508	     * fields. When a non-blank {@code addressLine1} is present, {@code addressLine1} and (when present)
509	     * {@code addressLine2} are normalized in place and the flat {@code address} is set to the composed
510	     * value: the normalized {@code addressLine1}, with a single space and the normalized
511	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the structured
512	     * lines are cleared and the flat {@code address} is normalized on its own, keeping the earlier
513	     * flat-address contract backward-compatible.
514	     *
515	     * @param owner the owner being created, mapped straight from the request
516	     */
517	    private void applyAddress(Owner owner) {
518	        if (!isBlank(owner.getAddressLine1())) {
519	            String line1 = normalizeAddress(owner.getAddressLine1());
520	            owner.setAddressLine1(line1);
521	            String composed = line1;
522	            if (!isBlank(owner.getAddressLine2())) {
523	                String line2 = normalizeAddress(owner.getAddressLine2());
524	                owner.setAddressLine2(line2);
525	                composed = line1 + " " + line2;
526	            } else {
527	                owner.setAddressLine2(null);
528	            }
529	            owner.setAddress(composed);
530	        } else {
531	            owner.setAddressLine1(null);
532	            owner.setAddressLine2(null);
533	            owner.setAddress(normalizeAddress(owner.getAddress()));
534	        }
535	    }
