537	    /**
538	     * Normalizes a submitted address into the form that is stored and returned. Leading and trailing
539	     * whitespace is removed, internal runs of whitespace are collapsed to a single space, the value is
540	     * upper-cased, and common street-type abbreviations are expanded ({@code ST -> STREET},
541	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). Abbreviations are only expanded when they form a whole
542	     * word, so an address such as {@code '  12  main  st '} normalizes to {@code '12 MAIN STREET'}.
543	     *
544	     * @param address the raw address value from the request (may be {@code null})
545	     * @return the normalized address, or an empty string when {@code address} is {@code null} or blank
546	     */
547	    private String normalizeAddress(String address) {
548	        if (address == null) {
549	            return "";
550	        }
551	        String collapsed = address.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
552	        if (collapsed.isEmpty()) {
553	            return "";
554	        }
555	        String[] tokens = collapsed.split(" ");
556	        StringBuilder sb = new StringBuilder(collapsed.length());
557	        for (int i = 0; i < tokens.length; i++) {
558	            if (i > 0) {
559	                sb.append(' ');
560	            }
561	            sb.append(expandAddressAbbreviation(tokens[i]));
562	        }
563	        return sb.toString();
564	    }
