566	    /**
567	     * Expands a single upper-cased address token from its common abbreviation to its full form, or
568	     * returns the token unchanged when it is not a recognised abbreviation.
569	     *
570	     * @param token an upper-cased whole-word address token
571	     * @return the expanded form ({@code STREET}, {@code ROAD}, {@code AVENUE}) or the original token
572	     */
573	    private String expandAddressAbbreviation(String token) {
574	        return switch (token) {
575	            case "ST" -> "STREET";
576	            case "RD" -> "ROAD";
577	            case "AVE" -> "AVENUE";
578	            default -> token;
579	        };
580	    }
