582	    /**
583	     * Builds the unified member id assigned to a newly created owner, formatted
584	     * {@code '<REGION><FY><HASH8><CHK>'} where {@code REGION} is the region derived from the owner's
585	     * postcode (falling back to the city when the postcode resolves to no known region), the same
586	     * derivation that yields the owner's locality; {@code FY} is the two-digit fiscal year of the owner's
587	     * (business-day-adjusted) {@code registrationDate}; {@code HASH8} is the first 8 upper-cased hex
588	     * characters of the SHA-256 digest of the owner's normalized telephone concatenated with the owner's
589	     * last name; and {@code CHK} is a single Luhn check digit computed over the digits of
590	     * {@code '<REGION><FY><HASH8>'} (e.g. {@code 'NSW261A2B3C4D7'}).
591	     * <p>
592	     * Should the computed id collide with an existing owner's {@code memberId}, it is de-duplicated by
593	     * appending {@code '-<n>'} with the smallest {@code n} of 2 or more that yields a value not already
594	     * held by any existing owner; the de-duplicated id is returned.
595	     *
596	     * @param owner the owner being created, with normalized telephone, postcode and registration date set
597	     * @return the assigned, collision-free member id
598	     */
599	    private String generateMemberId(Owner owner) {
600	        String region = OwnerLocality.of(owner.getCity(), owner.getPostcode());
601	        String fiscalYear = fiscalYearSuffix(owner.getRegistrationDate());
602	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
603	            .substring(0, 8).toUpperCase(Locale.ROOT);
604	        String core = region + fiscalYear + hash8;
605	        String base = core + luhnCheckDigit(core);
606	        Set<String> existing = this.clinicService.findAllOwners().stream()
607	            .map(Owner::getMemberId)
608	            .filter(id -> id != null)
609	            .collect(java.util.stream.Collectors.toSet());
610	        if (!existing.contains(base)) {
611	            return base;
612	        }
613	        int n = 2;
614	        while (existing.contains(base + "-" + n)) {
615	            n++;
616	        }
617	        return base + "-" + n;
618	    }
619	
620	    /**
621	     * Returns the two-digit fiscal-year suffix ({@code '<YY>'}) for the given date: the last two digits of
622	     * the calendar year in which that date's fiscal year (starting 1 July) begins. This is the same value
623	     * carried by the DTO's {@code fiscalYear} and embedded as the {@code FY} segment of the member id.
624	     *
625	     * @param date the (business-day-adjusted) registration date
626	     * @return the zero-padded two-digit fiscal-year suffix
627	     */
628	    private String fiscalYearSuffix(LocalDate date) {
629	        int year = date.getYear();
630	        int start = date.getMonthValue() >= 7 ? year : year - 1;
631	        return String.format("%02d", start % 100);
632	    }
633	
634	    /**
635	     * Computes a single Luhn check digit (0-9) over the digits contained in {@code value}. Non-digit
636	     * characters are skipped; the rightmost digit is doubled and every second digit thereafter, digits
637	     * exceeding 9 after doubling have 9 subtracted, and the check digit is {@code (10 - sum % 10) % 10}.
638	     *
639	     * @param value the value whose contained digits are summed
640	     * @return the Luhn check digit (between 0 and 9 inclusive)
641	     */
642	    private int luhnCheckDigit(String value) {
643	        int sum = 0;
644	        boolean dbl = true;
645	        for (int i = value.length() - 1; i >= 0; i--) {
646	            char c = value.charAt(i);
647	            if (c < '0' || c > '9') {
648	                continue;
649	            }
650	            int d = c - '0';
651	            if (dbl) {
652	                d *= 2;
653	                if (d > 9) {
654	                    d -= 9;
655	                }
656	            }
657	            sum += d;
658	            dbl = !dbl;
659	        }
660	        return (10 - (sum % 10)) % 10;
661	    }
662	
663	    /**
664	     * Computes the full lower-case hex SHA-256 digest of the UTF-8 bytes of the given value.
665	     *
666	     * @param value the value to hash
667	     * @return the 64-character lower-case hex SHA-256 digest
668	     */
669	    private String sha256Hex(String value) {
670	        try {
671	            byte[] digest = MessageDigest.getInstance("SHA-256")
672	                .digest(value.getBytes(StandardCharsets.UTF_8));
673	            StringBuilder sb = new StringBuilder(digest.length * 2);
674	            for (byte b : digest) {
675	                sb.append(String.format("%02x", b));
676	            }
677	            return sb.toString();
678	        } catch (NoSuchAlgorithmException e) {
679	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
680	        }
681	    }
