716	    /**
717	     * Computes the membership level assigned to a newly created owner, applying the household level ceiling.
718	     * The owner's own (uncapped) level cannot exceed one above the current maximum membership level among
719	     * their existing household members, where every level is measured against the household's current size
720	     * (the owner's just-computed {@code householdSize}). When the owner has no existing household member the
721	     * ceiling does not apply and the uncapped level is returned. The count is taken before the new owner is
722	     * persisted, so it excludes the owner being created; the existing members share the deterministic
723	     * {@code householdId} and any soft-deleted owner is ignored.
724	     *
725	     * @param owner the owner being created, with its {@code householdId} and {@code householdSize} already set
726	     * @return the owner's membership level, capped at one above the existing household maximum
727	     */
728	    private Integer computeMembershipLevel(Owner owner) {
729	        Integer householdSize = owner.getHouseholdSize();
730	        Integer ownLevel = this.ownerMapper.membershipLevelForHouseholdSize(owner, householdSize);
731	        String householdId = owner.getHouseholdId();
732	        int maxExisting = this.clinicService.findAllOwners().stream()
733	            .filter(existing -> !isDeleted(existing))
734	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
735	            .mapToInt(existing -> this.ownerMapper.membershipLevelForHouseholdSize(existing, householdSize))
736	            .max()
737	            .orElse(-1);
738	        if (maxExisting < 0) {
739	            return ownLevel;
740	        }
741	        return Math.min(ownLevel, maxExisting + 1);
742	    }
