825	     * @param date the effective registration date, supplied or defaulted
826	     * @return the same date when it is a business day, otherwise the next non-holiday business day
827	     */
828	    private LocalDate rollToBusinessDay(LocalDate date) {
829	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
830	            date = date.plusDays(1);
831	        }
832	        return date;
833	    }
