856	    private boolean isBulkSignupDay(LocalDate registrationDate) {
857	        long existing = this.clinicService.findAllOwners().stream()
858	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
859	            .count();
860	        return existing > BULK_SIGNUP_WARNING_THRESHOLD;
861	    }
862	
863	    /**
864	     * Rejects a create request whose supplied {@code registrationDate} is later than the server date. A
865	     * registration cannot be dated in the future. The check applies only to a date supplied in the request;
866	     * a {@code null} value (which is later defaulted to the server date) is accepted, and the comparison is
867	     * made against the supplied value before any business-day adjustment.
868	     *
869	     * @param registrationDate the registration date supplied in the request, or {@code null} when omitted
870	     * @throws FutureRegistrationDateException if a supplied registration date is later than the server date
871	     */
872	    private void rejectFutureRegistrationDate(LocalDate registrationDate) {
873	        if (registrationDate == null) {
874	            return;
875	        }
876	        LocalDate today = LocalDate.now();
877	        if (registrationDate.isAfter(today)) {
878	            throw new FutureRegistrationDateException(registrationDate, today);
879	        }
880	    }
881	
882	    private void rejectDailyLimitReached(LocalDate registrationDate) {
883	        long existing = this.clinicService.findAllOwners().stream()
884	            .filter(owner -> registrationDate.equals(owner.getRegistrationDate()))
885	            .count();
886	        if (existing >= DAILY_OWNER_LIMIT) {
887	            throw new DailyOwnerLimitExceededException(registrationDate, DAILY_OWNER_LIMIT);
888	        }
889	    }
890	
891	    /**
892	     * Rejects a create request whose owner collides with an existing owner on the single derived
893	     * {@code identityKey}. This one key consolidates the former separate telephone, email and household
894	     * duplicate checks: the create is rejected only when the new owner's WHOLE identity key exactly equals
895	     * an existing owner's. Because the (normalized) telephone is part of the key, two members of the same
896	     * household (same {@code householdId}) with different telephones have different keys and are both
897	     * allowed; only an exact full-key match is a duplicate. The owner's {@code householdId} has already
898	     * been computed (deterministically from the last name and postcode) before this check runs, so the
899	     * key compared here is the same one that is later returned.
900	     *
901	     * @param owner the owner being created, with normalized fields and its computed {@code householdId} set
902	     * @throws DuplicateIdentityException if an existing owner has the same identity key
903	     */
904	    private void rejectDuplicateIdentity(Owner owner) {
905	        String key = identityKey(owner);
906	        boolean taken = this.clinicService.findAllOwners().stream()
907	            .filter(existing -> !isDeleted(existing))
908	            .anyMatch(existing -> key.equals(identityKey(existing)));
909	        if (taken) {
910	            throw new DuplicateIdentityException(key);
911	        }
912	    }
913	
914	    /**
915	     * Flags a soft (possible) duplicate on the owner being created. A soft match is an existing owner that,
916	     * while not a hard {@code identityKey} duplicate (that stronger check has already run, so its whole
917	     * identity key differs), shares this owner's last-name {@link #soundex(String) soundex} and exact
918	     * postcode. When at least one such owner exists, {@code possibleDuplicate} is set {@code true} and
919	     * {@code possibleDuplicateOf} to the matching owner's id (the lowest id when several match, for
920	     * determinism); otherwise {@code possibleDuplicate} is set {@code false} and no match id is recorded. A
921	     * new owner with no postcode has nothing to match on and is never a possible duplicate.
922	     * <p>
923	     * A declared household member ({@code sharesHousehold}) is never flagged: it is a known household member
924	     * rather than a suspected duplicate.
925	     *
926	     * @param owner the owner being created, with normalized telephone and validated postcode already set
927	     * @param sharesHousehold whether the create declared the owner a household member
928	     */
929	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
930	        Integer matchId = null;
931	        if (!sharesHousehold && owner.getPostcode() != null) {
932	            String key = identityKey(owner);
933	            String soundex = soundex(owner.getLastName());
934	            matchId = this.clinicService.findAllOwners().stream()
935	                .filter(existing -> !isDeleted(existing))
936	                .filter(existing -> soundex.equals(soundex(existing.getLastName()))
937	                    && owner.getPostcode().equals(existing.getPostcode())
938	                    && !key.equals(identityKey(existing)))
939	                .map(Owner::getId)
940	                .filter(id -> id != null)
941	                .min(Comparator.naturalOrder())
942	                .orElse(null);
943	        }
944	        owner.setPossibleDuplicate(matchId != null);
945	        owner.setPossibleDuplicateOf(matchId);
946	    }
947	
948	    /**
949	     * Whether an existing owner has been soft-deleted. A soft-deleted owner is retained and still
950	     * readable, but is ignored by the create endpoint's duplicate and identity checks.
951	     *
952	     * @param owner an existing owner
953	     * @return {@code true} when the owner is flagged deleted, otherwise {@code false}
954	     */
955	    private boolean isDeleted(Owner owner) {
956	        return Boolean.TRUE.equals(owner.getDeleted());
957	    }
958	
959	    /**
960	     * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 digest of the normalized
961	     * telephone, the lower-cased email (or an empty string when absent) and the {@link #soundex(String)
962	     * soundex} of the last name, joined by {@code '|'} in that order before hashing (e.g. the digest of
963	     * {@code '+61412345678||F650'}). Telephone and email are stored already normalized, so the stored
964	     * values are used directly. This single 64-hex key is what duplicate detection compares.
965	     *
966	     * @param owner the owner whose identity key is being derived
967	     * @return the owner's identity key, a 64-character lower-case hex SHA-256 digest
968	     */
969	    private String identityKey(Owner owner) {
970	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
971	        String email = owner.getEmail() == null ? "" : owner.getEmail();
972	        String soundex = soundex(owner.getLastName());
973	        return sha256Hex(telephone + "|" + email + "|" + soundex);
974	    }
975	
976	    /**
977	     * Computes the American Soundex code of the given value: the retained (upper-cased) first letter
978	     * followed by three digits derived from the remaining consonants, right-padded with zeros or
979	     * truncated to length four. Non-letters are ignored; adjacent letters mapping to the same digit are
980	     * coded once (bridged across {@code 'H'}/{@code 'W'}), and vowels reset the run so a repeated code
981	     * separated by a vowel is coded twice. A {@code null} or letter-free value yields an empty string.
982	     *
983	     * @param value the value (typically a last name) to encode
984	     * @return the four-character Soundex code, or an empty string when there are no letters
985	     */
986	    private String soundex(String value) {
987	        if (value == null) {
988	            return "";
989	        }
990	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
991	        if (letters.isEmpty()) {
992	            return "";
993	        }
994	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
995	        char prev = soundexDigit(letters.charAt(0));
996	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
997	            char c = letters.charAt(i);
998	            if (c == 'H' || c == 'W') {
999	                continue;
1000	            }
1001	            char digit = soundexDigit(c);
1002	            if (digit != '0' && digit != prev) {
1003	                code.append(digit);
1004	            }
1005	            prev = digit;
1006	        }
1007	        while (code.length() < 4) {
1008	            code.append('0');
1009	        }
1010	        return code.toString();
1011	    }
1012	
1013	    /**
1014	     * Maps a single upper-case letter to its Soundex digit ({@code '1'}-{@code '6'}), or {@code '0'} for
1015	     * vowels and the non-coding letters {@code H}/{@code W}/{@code Y}.
1016	     *
1017	     * @param c an upper-case letter
1018	     * @return the letter's Soundex digit
1019	     */
1020	    private char soundexDigit(char c) {
1021	        return switch (c) {
1022	            case 'B', 'F', 'P', 'V' -> '1';
1023	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
1024	            case 'D', 'T' -> '3';
1025	            case 'L' -> '4';
1026	            case 'M', 'N' -> '5';
1027	            case 'R' -> '6';
1028	            default -> '0';
1029	        };
1030	    }
1031	
1032	    /**
1033	     * Computes the owner's deterministic {@code householdId}: the first 12 hex characters of the SHA-256
1034	     * digest of {@code '<normalizedLastName>|<postcode>'}, where the last name is normalized with
1035	     * {@link #normalizeForComparison} and an absent postcode contributes an empty string. Because the
1036	     * identifier is a pure function of last name and postcode, any two owners sharing those values share
1037	     * the household automatically, with no cross-owner mutation. The value is assigned to every owner,
1038	     * whether or not {@code sharesHousehold} was requested.
1039	     *
1040	     * @param owner the owner being created, with its validated postcode already set
1041	     * @return the deterministic household identifier
1042	     */
1043	    private String computeHouseholdId(Owner owner) {
1044	        String normalizedLastName = normalizeForComparison(owner.getLastName());
1045	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
1046	        return sha256Hex(normalizedLastName + "|" + postcode).substring(0, 12);
1047	    }
1048	
1049	    /**
1050	     * Normalizes a value for household-identity comparison: leading and trailing whitespace is
1051	     * removed, internal runs of whitespace are collapsed to a single space, and the result is
1052	     * lower-cased.
1053	     *
1054	     * @param value the raw value to normalize (may be {@code null})
1055	     * @return the normalized value, or an empty string when {@code value} is {@code null}
1056	     */
1057	    private String normalizeForComparison(String value) {
1058	        if (value == null) {
1059	            return "";
1060	        }
1061	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
1062	    }
1063	}
